package org.unicog.numberrace.ui;
import java.awt.*;import javax.swing.*;
public class GameIcon implements Icon {private final String type;private final int size;public GameIcon(String type,int size){this.type=type;this.size=size;}public int getIconWidth(){return size;}public int getIconHeight(){return size;}public void paintIcon(Component c,Graphics g,int x,int y){Graphics2D p=GameTheme.graphics(g);p.translate(x,y);p.scale(size/24.0,size/24.0);p.setColor(c.isEnabled()?c.getForeground():new Color(74,87,99));p.setStroke(new BasicStroke(3,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));switch(type){case "play":p.fillPolygon(new int[]{6,6,20},new int[]{3,21,12},3);break;case "add":p.drawLine(12,4,12,20);p.drawLine(4,12,20,12);break;case "save":p.drawLine(4,12,10,18);p.drawLine(10,18,21,5);break;case "edit":p.drawLine(5,19,19,5);p.drawLine(5,19,5,14);break;case "delete":p.drawRect(7,7,10,13);p.drawLine(4,5,20,5);break;case "exit":p.drawRect(3,4,10,16);p.drawLine(10,12,21,12);p.drawLine(17,8,21,12);p.drawLine(17,16,21,12);break;default:p.drawLine(5,5,19,19);p.drawLine(19,5,5,19);}p.dispose();}}